data.multiple-transcription-streams#Multiple:
You can process the same audio through multiple models simultaneously:
// Use a fast model for real-time preview
const fastStreamId = await client.ai.openTranscriptionStream(
  "whisper_tiny",
  (text) => console.log("Preview:", text),
  { startThreshold: 0.25, endWindow: 100 }
);
// Use a more accurate model for final results
const accurateStreamId = await client.ai.openTranscriptionStream(
  "whisper_small",
  (text) => console.log("Final:", text),
  { startThreshold: 0.3, endWindow: 500 }
);
// Feed audio to both streams efficiently
await client.ai.feedTranscriptionStream([fastStreamId, accurateStreamId], audioSamples);

data.using-ad4m-connect#Using ad4m-connect:
The easiest way to implement this flow is using our ad4m-connect library:
import Ad4mConnect from "@coasys/ad4m-connect";
const ui = Ad4mConnect({
  appName: "My First ADAM App",
  appDesc: "This is my first app here.",
  appDomain: "ad4m.dev",
  appIconPath: "https://i.ibb.co/GnqjPJP/icon.png",
  capabilities: [{ 
    with: { domain: "*", pointers: ["*"] }, 
    can: ["*"] 
  }],
});
// .connect() will show the authentication pop up
ui.connect().then((client) => {
  // Client is now authenticated with requested capabilities
});
If ad4m-connect could not find a running AD4M-executor, it will show a screen prompting the user to either download and run
the AD4M Launcher to provide other connection settings:When ad4m-connect was able to find a running AD4M-executor, it will begin the authentication flow:
Clicking on "Authorize" will trigger the request against the AD4M-executor and Launcher will open a pop-up prompting the user
with the nature of this request:
The application requesting access
The capabilities being requested
If the user approves the request, the Launcher will show a six-digit random secret code that needs to be entered into the app UI.
That way we have safely established that the network agent initiating the capability request (as seen from
the AD4M-executor) really is the UI the users wants to use.
(It could run on an external device, like the user's phone connecting through a proxy server).

data.capability-specification#Capability Spec:
When requesting capabilities, you need to specify:
{
  with: {
    domain: string | "*",     // Which perspective/domain
    pointers: string[] | "*"  // Which parts of the domain
  },
  can: string[] | "*"         // Which operations are allowed
}
Examples:
// Request access to everything (development only)
{ with: { domain: "*", pointers: ["*"] }, can: ["*"] }
// Request read-only access to a specific perspective
{ with: { domain: "perspective-uuid", pointers: ["*"] }, can: ["read"] }
// Request specific operations on a domain
{ with: { domain: "friends", pointers: ["*"] }, can: ["read", "add", "remove"] }

data.admin-credential-override#Admin Credenti:
For automated scenarios or system integration, the authentication handshake can be bypassed using an admin credential:
// In your application
const client = new Ad4mClient({
  adminCredential: "your-secret-here"
});
This is particularly useful for:
CI/CD pipelines
Testing environments
System services
Management interfaces (the AD4M Launcher uses this internally)
To enable this on the executor:
ad4m-executor run --admin-credential your-secret-here
⚠️ Security Note: The admin credential grants full access to the executor. Use it carefully and never expose it in client-side code or public repositories.

data.useclient#useClient:
The most fundamental hook that provides access to the AD4M client instance.
import { useClient } from '@coasys/ad4m-react-hooks';
function MyComponent() {
  const { client, error, reload } = useClient();
  if (error) {
    return <div>Error connecting to AD4M: {error}</div>;
  }
  if (!client) {
    return <div>Connecting to AD4M...</div>;
  }
  return <div>Connected to AD4M</div>;
}
The hook returns:
client: The AD4M client instance
error: Any connection errors
reload: Function to retry the connection
mutate: Function to update the cached client instance

data.useagent#useAgent:
Fetches and caches agent data by DID, with support for profile formatting.
import { useAgent } from '@coasys/ad4m-react-hooks';
function AgentProfile({ agentClient, did }) {
  const { agent, profile, error } = useAgent({
    client: agentClient,
    did,
    formatter: (links) => ({
      name: links.find(l => l.data.predicate === 'name')?.data.target,
      bio: links.find(l => l.data.predicate === 'bio')?.data.target
    })
  });
  if (error) return <div>Error: {error}</div>;
  if (!agent) return <div>Loading...</div>;
  return (
    <div>
      <h2>{profile?.name}</h2>
      <p>{profile?.bio}</p>
      <p>DID: {agent.did}</p>
    </div>
  );
}

data.useme#useMe:
Provides access to the current agent's data and status.
import { useMe } from '@coasys/ad4m-react-hooks';
function MyProfile({ agentClient }) {
  const { me, status, profile, error } = useMe(agentClient, (links) => ({
    name: links.find(l => l.data.predicate === 'name')?.data.target,
    bio: links.find(l => l.data.predicate === 'bio')?.data.target
  }));
  if (error) return <div>Error: {error}</div>;
  if (!me) return <div>Loading...</div>;
  return (
    <div>
      <h2>{profile?.name}</h2>
      <p>{profile?.bio}</p>
      <p>Status: {status.isUnlocked ? 'Unlocked' : 'Locked'}</p>
    </div>
  );
}

data.useperspective#usePerspective:
Fetches and subscribes to a single perspective by UUID.
import { usePerspective } from '@coasys/ad4m-react-hooks';
function Perspective({ client, uuid }) {
  const { data } = usePerspective(client, uuid);
  const { perspective, synced } = data;
  if (!perspective) return <div>Loading...</div>;
  return (
    <div>
      <h2>{perspective.name}</h2>
      <p>Synced: {synced ? 'Yes' : 'No'}</p>
      <p>UUID: {perspective.uuid}</p>
    </div>
  );
}

data.useperspectives#usePerspectives:
Provides access to all perspectives and handles real-time updates.
import { usePerspectives } from '@coasys/ad4m-react-hooks';
function PerspectivesList({ client }) {
  const { perspectives, neighbourhoods, onLinkAdded, onLinkRemoved } = usePerspectives(client);
  useEffect(() => {
    const handleNewLink = (perspective, link) => {
      console.log(`New link in ${perspective.name}:`, link);
    };
    onLinkAdded(handleNewLink);
    return () => onLinkRemoved(handleNewLink);
  }, []);
  return (
    <div>
      <h2>All Perspectives</h2>
      <ul>
        {Object.values(perspectives).map(p => (
          <li key={p.uuid}>{p.name}</li>
        ))}
      </ul>

      <h2>Neighbourhoods</h2>
      <ul>
        {Object.values(neighbourhoods).map(p => (
          <li key={p.uuid}>{p.name}</li>
        ))}
      </ul>
    </div>
  );
}

data.collection-mode-default#Collection Mode:
import { useLiveQuery } from '@coasys/ad4m-react-hooks';
import { Todo } from './models/Todo';
function TodoList({ perspective }) {
  const { data, loading, error, totalCount, loadMore } = useLiveQuery(
    Todo,
    perspective,
    {
      query: { where: { status: "active" } },
      pageSize: 10,
    }
  );
  if (error) return <div>Error: {error}</div>;
  if (loading && data.length === 0) return <div>Loading...</div>;
  return (
    <div>
      <h2>Todos ({totalCount})</h2>
      {data.map(todo => (
        <div key={todo.id}>
          <h3>{todo.title}</h3>
          <p>{todo.description}</p>
        </div>
      ))}
      {data.length < totalCount && (
        <button onClick={loadMore} disabled={loading}>
          {loading ? 'Loading...' : 'Load More'}
        </button>
      )}
    </div>
  );
}

data.single-instance-mode#Single-Instance Mod:
When you provide id in options, the hook returns a single item instead of an array:
function TodoDetail({ perspective, todoId }) {
  const { data: todo, loading, error } = useLiveQuery(
    Todo,
    perspective,
    { id: todoId }
  );
  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!todo) return <div>Not found</div>;
  return <h2>{todo.title}</h2>;
}

data.parent-scoped-queries#Parent-Scoped Quer:
Filter results to children of a specific parent:
function RecipeComments({ perspective, recipe }) {
  const { data: comments } = useLiveQuery(
    Comment,
    perspective,
    {
      parent: { model: Recipe, id: recipe.id }
    }
  );
  return (
    <ul>
      {comments.map(c => <li key={c.id}>{c.body}</li>)}
    </ul>
  );
}

data.vue-usage#Vue Usage:
The Vue hook has the same API but returns Vue Ref-wrapped values and accepts ComputedRef<PerspectiveProxy> for the perspective parameter:
import { useLiveQuery } from '@coasys/ad4m-vue-hooks';
const { data, loading, error, totalCount, loadMore } = useLiveQuery(
  Todo,
  perspective,  // Can be a ComputedRef
  { pageSize: 10 }
);
// data.value is T[] (collection) or T | null (single-instance)
The Vue hook automatically re-subscribes when the perspective ref changes, and cleans up subscriptions on unmount.

data.best-practices#Best Practices:
Always handle loading and error states
if (error) return <ErrorComponent error={error} />;
if (!data) return <LoadingComponent />;
Clean up subscriptions
useEffect(() => {
  const callback = (perspective, link) => { /* ... */ };
  onLinkAdded(callback);
  return () => onLinkRemoved(callback);
}, []);
Use formatters for consistent data structure
const formatter = (links) => ({
  name: links.find(l => l.data.predicate === 'name')?.data.target,
  bio: links.find(l => l.data.predicate === 'bio')?.data.target
});
Leverage caching
// The hooks handle caching automatically
const { data: perspective1 } = usePerspective(client, uuid1);
const { data: perspective2 } = usePerspective(client, uuid2);
Use TypeScript for better type safety
// useLiveQuery is fully typed — generics are inferred from the model class
const { data } = useLiveQuery(Todo, perspective);
// data is Todo[] with full autocomplete

data.using-transactions#Using Transactions:
The recommended way to use batch operations is Ad4mModel.transaction(), which creates a batch, runs your callback, and commits only on success:
await Ad4mModel.transaction(perspective, async (tx) => {
  const recipe = await Recipe.create(perspective, { name: "Cake" }, { batchId: tx.batchId });
  const comment = new Comment(perspective);
  comment.body = "Looks great!";
  await comment.save(tx.batchId);
  // Relation methods also accept batchId
  await recipe.addComments(comment, tx.batchId);
});
// All operations commit together, or none do if an error is thrown
If any operation inside the callback throws, the batch is never committed and no changes are persisted.

data.complex-data-models#Complex Data Models:
When your application needs to maintain relationships between multiple entities:
await Ad4mModel.transaction(perspective, async (tx) => {
  const userProfile = await UserProfile.create(perspective, { name: "Alice" }, { batchId: tx.batchId });
  const userSettings = await UserSettings.create(perspective, { theme: "dark" }, { batchId: tx.batchId });
  for (const preference of userPreferences) {
    await preference.save(tx.batchId);
  }
});

data.bulk-operations#Bulk Operations:
When performing operations on multiple items:
await Ad4mModel.transaction(perspective, async (tx) => {
  for (const task of tasks) {
    task.status = 'completed';
    await task.save(tx.batchId);
  }
});

data.state-transitions#State Transitions:
When an operation requires multiple coordinated changes:
await Ad4mModel.transaction(perspective, async (tx) => {
  await sourceList.removeTask(task, tx.batchId);
  await targetList.addTask(task, tx.batchId);
  task.status = 'moved';
  await task.save(tx.batchId);
});

data.creating-related-subjects#Creating Relat:
await Ad4mModel.transaction(perspective, async (tx) => {
  // Create main subject
  const post = await BlogPost.create(perspective, { title: "My First Post" }, { batchId: tx.batchId });
  // Create related subjects
  const comments = initialComments.map(text => {
    const c = new Comment(perspective);
    c.content = text;
    c.postId = post.id;
    return c;
  });
  // Save all related subjects in the same transaction
  await Promise.all(comments.map(c => c.save(tx.batchId)));
});

data.validation-before-commit#Validation Befo:
Validate data before any writes — if validation fails, the thrown error prevents commit:
await Ad4mModel.transaction(perspective, async (tx) => {
  // Validate all ingredients first
  for (const ingredient of ingredients) {
    if (!await validateIngredient(ingredient)) {
      throw new Error(`Invalid ingredient: ${ingredient}`);
    }
  }
  // If all valid, proceed with updates
  recipe.ingredients = ingredients;
  await recipe.save(tx.batchId);
  // Create ingredient references
  for (const ingredient of ingredients) {
    const ref = new IngredientReference(perspective);
    ref.recipeId = recipe.id;
    ref.ingredientId = ingredient.id;
    await ref.save(tx.batchId);
  }
});
// Nothing is persisted if validation threw

data.advanced-manual-batch-control#Advanced::
For lower-level control (e.g. mixing model operations with raw link operations), you can manage batches directly via PerspectiveProxy:
const batchId = await perspective.createBatch();
try {
  // Add multiple links in the batch
  await perspective.add(link1, 'shared', batchId);
  await perspective.add(link2, 'shared', batchId);

  // Remove a link in the same batch
  await perspective.remove(oldLink, batchId);

  // Update a link in the batch
  await perspective.update(existingLink, newLink, batchId);
  // Model operations also accept batchId
  const recipe = new Recipe(perspective);
  recipe.title = "Chocolate Cake";
  await recipe.save(batchId);
  // Commit all changes atomically
  const result = await perspective.commitBatch(batchId);
  console.log('Added:', result.additions.length);
  console.log('Removed:', result.removals.length);
} catch (error) {
  // If any operation fails, none of the changes are applied
  console.error('Batch operation failed:', error);
}
Under the hood, Ad4mModel.transaction() calls createBatch() and commitBatch() for you.

data.migration-guide#Migration Guide:
Existing code using manual createBatch()/commitBatch() will continue to work. To modernize:
// Before: manual batch management
const batchId = await perspective.createBatch();
try {
  await recipe.save(batchId);
  await comment.save(batchId);
  await perspective.commitBatch(batchId);
} catch (error) {
  console.error(error);
}
// After: transaction() handles it
await Ad4mModel.transaction(perspective, async (tx) => {
  await recipe.save(tx.batchId);
  await comment.save(tx.batchId);
});
No schema changes or data migration is required.

data.anatomy-of-an-expression#Anatomy of an E:
Every Expression consists of:
interface Expression {
    // The DID of the agent who created this Expression
    author: string;

    // When the Expression was created
    timestamp: string;

    // The actual data/content
    data: any;

    // Which Language this Expression belongs to
    language: LanguageRef;

    // Cryptographic proof of authorship
    proof: {
        // These flags are added by AD4M during retrieval
        valid?: boolean;    // True if signature verification succeeded
        invalid?: boolean;  // True if signature verification failed
        // The actual stored proof data
        signature: string;  // The cryptographic signature
        key: string;       // Key path in the author's DID Document used for signing
    };
}
For example:
{
  "author": "did:key:zQ3shv5VUAbtY5P1jGsPzy7L27FTxeDv2hnhVp9QT3ALNCnQ2",
  "timestamp": "2023-06-21T14:47:48.935Z",
  "data": "Hello World!",
  "language": {
    "address": "literal"
  },
  "proof": {
    "valid": true,     // Added by AD4M during retrieval
    "invalid": false,  // Added by AD4M during retrieval
    "signature": "...", // The stored signature
    "key": "..." // Key path in the author's DID Document used for signing
  }
}

data.creating-expressions#Creating Expression:
When an agent wants to share data, they create an Expression through a Language:
// Create an Expression using the literal Language
const url = await ad4m.expression.create(
    "Hello World!", 
    "literal"
);
// Returns: literal://base64encoded-content
// Create an Expression using a custom Language
const socialPost = await ad4m.expression.create(
    { text: "My first post!" },
    "QmSocialApp123" // Language hash
);
// Returns: QmSocialApp123://post789
Behind the scenes, AD4M:
Passes the data to the specified Language
The Language stores/processes the data and returns an address
AD4M signs the Expression with the agent's keys
Returns the full Expression URL

data.signature-verification#Signature Verific:
When you retrieve an Expression through ad4m.expression.get(), AD4M automatically:
Resolves the author's DID to get their public keys
Verifies that the signature matches:
The author's DID
The Expression's data
The timestamp
Using the specified key from the author's DID Document
Enriches the Expression object with verification flags:
proof.valid: Set to true if verification succeeded
proof.invalid: Set to true if verification failed
These verification flags are not stored with the Expression – they are computed on-the-fly during retrieval to ensure fresh verification against the current state of the author's DID Document.
// When you retrieve an Expression
const expression = await ad4m.expression.get("QmSocialApp123://post789");
// AD4M has already verified the signature
if (expression.proof.valid) {
    // The Expression is authentic and unmodified
    console.log("Verified expression from:", expression.author);
} else {
    // The signature verification failed
    console.warn("Could not verify expression authenticity");
}

data.quick-reference-graph-traversal-syntax#Q:
SurrealDB's graph traversal operator (->) enables powerful multi-hop queries:
// Basic syntax: node->link[filter][index].field
out->link[WHERE predicate = 'flux://entry_type'][0].out.uri
// Components:
// - out                     : Start from target node
// - ->link                  : Follow link edges
// - [WHERE predicate = ...] : Filter links (optional)
// - [0]                     : Get first result (array index)
// - .out.uri                : Access target URI
Key Functions:
fn::parse_literal(uri) - Extract values from AD4M literal URIs (handles literal://string:, literal://number:, literal://json:, etc.)
Fields & Indexes:
predicate — Indexed independently and in composites
source, target — Indexed independently and in composites with predicate
(in, predicate), (out, predicate) — Composite indexes (pair in.uri/out.uri with predicate for best performance)
in.uri, out.uri — Graph edge references, resolved via the node table's unique URI index (not independently indexed on the link table)

data.basic-query#Basic Query:
// Get all links
const links = await perspective.querySurrealDB('SELECT * FROM link');
console.log(links);
// [
//   { source: "user://alice", predicate: "follows", target: "user://bob", ... },
//   { source: "post://123", predicate: "likes", target: "user://alice", ... }
// ]

data.filtering#Filtering:
// Filter links by predicate
const follows = await perspective.querySurrealDB(
  "SELECT * FROM link WHERE predicate = 'follows'"
);
// Multiple conditions
const recentLikes = await perspective.querySurrealDB(
  "SELECT * FROM link WHERE predicate = 'likes' AND timestamp > '2024-01-01T00:00:00Z'"
);

data.aggregations#Aggregations:
// Count links by predicate
const stats = await perspective.querySurrealDB(
  "SELECT predicate, count() as total FROM link GROUP BY predicate"
);
// [
//   { predicate: "follows", total: 42 },
//   { predicate: "likes", total: 156 }
// ]
// Count total links
const totalLinks = await perspective.querySurrealDB(
  "SELECT count() as total FROM link"
);
// Count unique sources using GROUP BY
const uniqueSources = await perspective.querySurrealDB(
  "SELECT source FROM link GROUP BY source"
);
// uniqueSources.length gives you the count of unique sources

data.️-avoid-subqueries#⚠️ Avoid Subqueries:
Subqueries (IN (SELECT ...)) can be very slow. Use the -> traversal operator instead:
// ❌ SLOW - Uses subquery
const bad = await perspective.querySurrealDB(
  "SELECT * FROM link WHERE source IN (SELECT target FROM link WHERE source = 'user://alice')"
);
// ✅ FAST - Use graph traversal operator for multi-hop
const good = await perspective.querySurrealDB(
  "SELECT out->link[WHERE predicate = 'posted'].out.uri AS posts FROM link WHERE in.uri = 'user://alice' AND predicate = 'follows'"
);

data.basic-traversal#Basic Traversal:
// Forward: Find all users that Alice follows
const aliceFollows = await perspective.querySurrealDB(
  "SELECT target FROM link WHERE in.uri = 'user://alice' AND predicate = 'follows'"
);
// Reverse: Find all users who follow Alice
const aliceFollowers = await perspective.querySurrealDB(
  "SELECT source FROM link WHERE out.uri = 'user://alice' AND predicate = 'follows'"
);
// Bidirectional: All connections involving Alice
const aliceConnections = await perspective.querySurrealDB(
  "SELECT source, target FROM link WHERE (in.uri = 'user://alice' OR out.uri = 'user://alice') AND predicate = 'follows'"
);

data.filtering-1#Filtering:
// By timestamp range
const recentLinks = await perspective.querySurrealDB(
  "SELECT * FROM link WHERE in.uri = 'user://alice' AND timestamp > '2024-01-01T00:00:00Z' AND timestamp < '2024-12-31T23:59:59Z'"
);
// By author
const bobsLinks = await perspective.querySurrealDB(
  "SELECT * FROM link WHERE author = 'did:key:bob' AND predicate = 'posted'"
);
// Filter on multi-hop properties (find children of a specific type)
const subgroups = await perspective.querySurrealDB(`
  SELECT out.uri AS subgroup
  FROM link
  WHERE in.uri = 'conversation://456'
    AND predicate = 'ad4m://has_child'
    AND out->link[WHERE predicate = 'flux://entry_type'][0].out.uri = 'flux://conversation_subgroup'
`);

data.multi-hop-traversal#Multi-Hop Traversal:
Use the -> operator to traverse multiple hops in a single efficient query:
// 2-hop: Friends of friends
const friendsOfFriends = await perspective.querySurrealDB(`
  SELECT out->link[WHERE predicate = 'follows'].out.uri AS friend_of_friend
  FROM link
  WHERE in.uri = 'user://alice' AND predicate = 'follows'
`);
// Deduplicate in JS (friend_of_friend is an array per row — flatten first):
// [...new Set(friendsOfFriends.flatMap(f => f.friend_of_friend))]
// 2-hop: User profiles via follows
const profiles = await perspective.querySurrealDB(`
  SELECT 
    out.uri AS user,
    out->link[WHERE predicate = 'has_profile'][0].out.uri AS profile
  FROM link
  WHERE in.uri = 'user://alice' AND predicate = 'follows'
`);
// 2-hop: Child items with their types
const childTypes = await perspective.querySurrealDB(`
  SELECT 
    out.uri AS child,
    out->link[WHERE predicate = 'flux://entry_type'][0].out.uri AS type
  FROM link
  WHERE in.uri = 'parent://123' AND predicate = 'ad4m://has_child'
`);

data.parsing-literal-values#Parsing Literal V:
AD4M stores values as literal URIs. Use fn::parse_literal() to extract them:
Literal URI	Parsed Value	literal://string:Hello	"Hello"	literal://number:42	42	literal://boolean:true	true	literal://json:{"data":"value"}	extracts .data field	
const query = `
  SELECT 
    out.uri AS id,
    fn::parse_literal(out->link[WHERE predicate = 'flux://title'][0].out.uri) AS title,
    fn::parse_literal(out->link[WHERE predicate = 'flux://body'][0].out.uri) AS body,
    fn::parse_literal(out->link[WHERE predicate = 'flux://count'][0].out.uri) AS count
  FROM link
  WHERE in.uri = 'parent://789' AND predicate = 'ad4m://has_child'
`;
const results = await perspective.querySurrealDB(query);
// { id, title: "Hello", body: "World", count: 42 }

data.counting-and-unique-values#Counting and:
// Count conversation subgroups
const countQuery = `
  SELECT count() AS count
  FROM link
  WHERE in.uri = 'conversation://abc'
    AND predicate = 'ad4m://has_child'
    AND out->link[WHERE predicate = 'flux://entry_type'][0].out.uri = 'flux://conversation_subgroup'
`;
const result = await perspective.querySurrealDB(countQuery);
// Get unique participants from nested items
const participantsQuery = `
  SELECT VALUE out->link[WHERE predicate = 'ad4m://has_child'].author
  FROM link
  WHERE in.uri = 'conversation://xyz'
    AND predicate = 'ad4m://has_child'
    AND out->link[WHERE predicate = 'flux://entry_type'][0].out.uri = 'flux://conversation_subgroup'
    AND out->link[WHERE predicate = 'ad4m://has_child'].author IS NOT NONE
`;
// Returns nested author arrays (one per subgroup) — flatten and deduplicate client-side

